//! svstar2 — Varix STAR II · VE 图形引擎册 · 用户态服务落位。
//!
//! # 落位依据（★ 位置铁律，勿改 ★）
//!
//! 《VE Varix STAR II · 总纲与施工书》铁律 6：
//! > **内核红线**：全部功能针对 VARIX Rust 内核编写；内核态只留合成裁决与安全，
//! > VE 全部活在用户态服务；引擎崩溃零拖垮。
//!
//! 读法（勿误读为"能用前端语言写"）：
//! - 「用户态服务」指**不在内核态特权上下文运行**——崩溃不拖垮内核；
//! - 本仓内核树是 no_std Rust（`kernel/varix/Cargo.toml` 的 `[dependencies]` 为空，
//!   `[[bin]]` 带 `required-features = ["kernel-image"]`）；
//! - TypeScript 编译出 JS，**必须靠 V8/JSC 运行时才能执行**，内核态无堆、无 GC、
//!   无动态链接，装不下也不允许跑；且 GC 停顿与内核延迟硬要求直接冲突。
//! - 故 VE 全 6400 项落地为 **Rust**，本目录即其家。
//!
//! 目录名沿用仓库既有命名先例（`svstar` 服务守护域 → `svstar2` 承载 STAR II）。
//!
//! # 命名约定
//!
//! | 前缀 | 含义 |
//! | --- | --- |
//! | `vea01` … `vea10` | VE-A 域（内核图形抽象层，F0001-F0200）|
//! | `veb01` … `veb10` | VE-B 域（GPU 驱动矩阵，F0201-F0400）|
//! | 后续按域顺延 | 域字母与册内 `VE-x` 一致 |
//!
//! # 与既有模块的关系纪律（对齐 svstar/ 与 genstar2/ 的域约）
//!
//! - 本目录只放 **VE 册**功能；CoRun 册（操作系统本体/三通道兼容）走既有内核模块，
//!   CGPU 册（计算内核）另设落位——三册互不混装；
//! - 每个模块自带 `run_*_checks() -> CheckSet` 自检并登记进本域聚合器，
//!   聚合器在 `robust.rs` 以单行注册（不占 domains 定长数组名额）；
//! - 每个模块带 `#[cfg(test)]` 单元测试，宿主侧 `cargo test` 直跑；
//! - 全部确定性算法、零 IO、可序列化：时间用逻辑 tick 注入，不用墙钟——
//!   保证回归可复现、对拍可重现（规格对拍红线）。
//!
//! # 域内模块地图（施工中，随进度增补）
//!
//! | 模块 | 功能 | 判据锚 |
//! | --- | --- | --- |
//! | [`veh11_reverb`] | F1411 混响区与环境声学（分区即氛围：预设四族具名+Custom 空槽，跨分区序关系单调不靠互异性证明；卷积+备用三态 FSM 带迟滞死区防抖，MAC/样本恒等于 IR 长度故预算表与采样率解耦；IR 校验取长度双端+采样率逐位（不静默重采样，相位错的混响极难定位），延迟走 uniform-partitioned 闭式 (K−1)·P/fs 而非 L/fs（后者差一个数量级）；过渡时长=clamp(距离/速度) 且速度趋零钳上界不发散，频率量走几何插值中点恰为 √(ab)；边界以签名兑现——渲染入口只接听者坐标，播放链想用混响得先改签名） | VE 册 #VE-F1411 |
//! | [`veh15_loudness_service`] | F1414 引擎级响度归一服务（批量 LUFS/TruePeak 扫描：预设表数据驱动可扩展但**拒收非法目标**（NaN/peak>0/目标越界），R128=−23/流媒体=−14 按锚点写死；指纹缓存键=**哈希+算法版本**（只用哈希是最常见的假优化——算法升级后哈希未变⇒返回旧口径值而界面显示新算法名），缓存是纯函数记忆故命中判定与扫描历史无关；全量扫描**有且只有**两个触发条件（首次/算法升级），增量只排未命中项且**修改文件与新增同等入队**（只认新增会漏掉最需要重测的改件）；增益两段分开——响度对齐与 True Peak 限幅处置不同，合并成一个数则报告说不清做了哪件事；静音不施增益（把 −70 抬到 −14 会把底噪放大 56dB）；报告首行必带 preset/algo/gate 口径，离开模块仍自解释） | VE 册 #VE-F1414 |
//! | [`veh15_checks`] | F1414 域自检（判据逐条映射锚点六条，42 项分 a/b/c 三族；每个防退化设计点都配反例判据——只断「新版不命中旧键」时「根本不用缓存」也能过，故必须同时断「同版命中旧键」与「仅指纹键会误命中」；判据区零 panic 面，越界切片`fb.0[16..]` 这类写法在实现正确时反而 panic） | VE 册 #VE-F1414 |
//! | [`vek10_fxaa`] | F2010 抗锯齿四法之 FXAA（单 pass 全屏：亮度对比边缘检测→边缘方向→定向模糊，Console/FXAA 3.11 质量档；低/中/高三预设阈值+跨度+步数三轴皆不同，档位强度用 touched 集合包含关系 S(low)⊆S(mid)⊆S(high) 验证；输出取值集闭包 {中心,A,B} 逐位相等故闭包判据用 == 而非近似；序位守卫三违规带三要素；模糊代价以合成高频图案的高频能量比作可复算证据；双线性采样是正确性前提——最近邻会让 A/B 落回中心像素使 FXAA 退化为空操作而结构判据全绿；与 CAS 联动给警告而非静默关掉） | VE 册 #VE-F2010 |
//! | [`vek11_taa`] | F2011 抗锯齿四法之 TAA（历史帧累积+子像素抖动：Halton(2,3) 8 相位，两底数分别进位；原始包围盒约 0.8125×0.7778 像素，由 normalize_scale() 按实测反推归一系数使 x 方向恰好铺满 1.0 像素，系数不写死常数；校验管线 velocity reject + 深度/法线相似度 + 场景切换强制失效，失效一律**权重精确归零**而非打折——打折会让鬼影残留，故用 enum HistoryUse 两态表达让『打折后仍在用』无法书写；clipping 用 3×3 邻域 min/max AABB 且**先 clip 后混合**（顺序交换即色偏），方差 clipping 由邻域矩导出；降级显性：速度缓冲缺失退化为几何启发校验并产 DegradeRecord 告警，静默降级时记录为空、判据立刻转红；历史显存 16 字节/像素含深度（只算颜色会低估 1/3），超配额拒绝 TAA 并回退 FXAA 建议；与 F2009 MSAA 互斥且被丢弃方具名；闪烁证据可复算——权重跳变的亮度台阶实测为单步的 3.6 倍） | VE 册 #VE-F2011 |
//! | [`vek12_smaa`] | F2012 抗锯齿四法之 SMAA 预留（**预留落成可被检查的结构**，不写成一句注释：三 pass 签名按 F1871 同构契约冻结 v1 且以 FNV 指纹机器锚定（只吃字节不吃 f32——浮点载荷会让同一份表在不同优化级别下算出不同指纹，那是假冻结锚）；**预留返回成功在类型上不可表达**——SmaaStubResult 的 Ok 侧是不可构造的 Infallible；三 pass 建成**真数据流**并断链式性/无悬挂读/格式往返；挂载位与 TAA **同位**，互斥由槽位相等**推导**而非手写互斥表；四法选型决策树走**全笛卡尔积 72 组合**穷举验证（无空洞/无死规则/无死兜底）；成本**数据单源**——登记表直引三法公开常量，行内定点快照仅作变更检测锚；预留零运行时用 TouchCounter **可数**证明；判据 83 项含 16 个反向变体，变异 harness 20/20 全捕获） | VE 册 #VE-F2012 |
//! | [`vek13_ppdbg`] | F2013 后处理调试数据（三类负载落成可被订阅的结构：**效果统计流**每帧每效果一行（开关/关键参数/独占耗时），环形定容覆盖而非增长，降频用 stride 加倍 + 跳过计数 + 告警三件齐做且**写入 + 跳过 == 逻辑帧数**守恒（不丢不重）；**独占耗时与总耗时两个口径两个字段**——拿总耗时冒充分享会让「独占」二字失去意义，参数摘要走**定点整数**而非 f32（`-0.0`/`NaN` 位模式会让同一份参数在不同优化级别下算出不同摘要，那是假对账），且 `±0.0` 归一、NaN 归哨兵；**RT 拾取流**逐级透视：`depth = d` 恰回溯 d 段祖先（能选中 ≠ 能看到前面那一级），超带宽走**下采样拷贝档**且**保留请求档位**——静默降档会让 VE-Y 拿着 1/4 分辨率当全分辨率解读，降到最低档仍超预算则**拒绝并记专属码**（降档是手段，不是无限降）；**图结构快照**节点/边/拓扑序/别名复用四要素齐备：拓扑序走 Kahn + 按 id 序出队保证**确定性**（倒序插入语料下仍满足边约束），出队数不足即有环⇒**拒绝出残缺序**（残缺序会让 VE-Y 画出缺边的图），别名复用做成「多节点声明同 alias ⇒ 复用计数 == 2 且**物理 RT 数不增**」，alias 只与物理表 `node` 槽单向比对（同时比 handle 会错配但不报错）；版本漂移**拦截而非记一笔**——记一笔就照发的话 VE-Y 会把旧拓扑画成当前拓扑；**发行版零成本由「根本不进入」保证**：Release 档 `payload_builds` 不递增（不是构建完再抹掉），强行请求只记次数 + P1，双向验证（Debug 档真递增作对照 + Release 档百次强行仍恰为 0）；零成本由**单调计数器** `build_entries` 物质保证——`payload_builds` 是净值可被「自增再减回」洗白（实测变异全绿放过），单调计数不可，故断「Debug 恰 1 + Release 恰 0」；构建档位与「本帧有数据」分列两个类型（一个 bool 表达两件事必错）；判据 118 项分 a/b/c/d 四族（d 族为聚合门禁：分族完整性两侧不同口径对账），含反向变体与 16 项逐项变异双向验证） | VE 册 #VE-F2013 |
//! | [`vek14_ppbudget`] | F2014 后处理性能预算（**十效果×三硬件档每像素成本常数表**（实测定标，F2017 回灌只增不减），组合预估 = 线性叠加 + **共享优化注记**（TAA 与 MB 共享速度缓冲按 400‰ 减免**且只减共享方那一份**，非共享对一分不减）；分辨率是成本的一次因子（像素数翻倍成本即翻倍，无与分辨率无关的固定项）；**预算联动固定次序** TAA 采样比 → Bloom mip → DoF/MB 样本 → 色彩精度，次序单源与 F2015 档位表对齐，**SMAA 预留不参与**（无渲染实现，降了也不变）；**次序守卫**：降不了的步必须告警 + 遥测标记（F2059），不得静默跳过；**20% 修正门**按**相对比例且两侧同阈**判定（只判正偏差会让「模型高估」永久逃逸，而那恰恰最该修正），阈值**含端点**，模型估 0 而实测有开销按最大偏差立项；**三方裁决** F1832 同构：用户覆盖 > 档位 > 预算临时，冲突时档位优先回改；**打点共享 F2013 设施**（复用其 `RawTiming` 口径而非另建一套——另建会让「独占耗时」有两个口径），打点自身开销 >1%（千分数 10‰，非 1000‰）⇒ stride 倍增降频，降到底仍超则**如实停并记专属码**（测量不能扰动被测系统——方法学红线），降频跳过的打点**照常计数**（否则「采了多少样」会被误读成丢数据）；K 段预算总账环形定容，`覆盖数 == 写入数 − 容量` 两轮均成立） | VE 册 #VE-F2014 |
//! | [`vek15_pptier`] | F2015 后处理质量档位（三档参数表**单源**——高=全效果全精度（TAA 8 相位/DoF 64/全 mip 链 7）、中=TAA 标准 4 相位/DoF 32/半 mip 4、低=FXAA 替代 TAA/DoF 关/Bloom 单级，SMAA 三档全关（F2012 预留不参与）；子开关**只降不升**——用户可单独关某效果/降精度/降 knob/整关 AA，SMAA 开/AA 换种/knob 超档=档位表外拒绝（档位是成本与观感的承诺包，放行上调会让档位名与实际成本脱钩、D04 与 F2014 预算联动全对不上账），整关 AA 连带 TAA 相位归零（名义关了还在转=假关）；D04 降质链映射**单源** 0..=100 三行无缝覆盖、缺行显性拒绝不回绕不猜、双向往返 tier→代表值→tier 恒等不出带；三方裁决 F1832 同构——用户覆盖>档位>预算临时，**在场异见才计冲突**（缺席≠异见）、全缺席保持现役（不发明默认值）；切换**帧边界生效**（F1762 同规则/F2002 重组协议同款）——请求只写暂存不动现役、帧边界一次性换装 epoch 单调、暂存一次性消费二次应用拿不到、非法请求零暂存；档位记忆——魔数 0xF215+版本+8 位 FNV 校验（FNV-1a 对单比特翻转数学上全检出，8 位换 1 数据字节装下十效果 10 位子开关），损坏回退默认档+告警、**自洽未知版本显性拒绝不静默回退**（回退会无声丢用户选择，两者必须分型）、v1→v2 迁移保留用户档位补默认零位；十效果闭集与诊断袋复用 F2014 单源（另立一份枚举会让两表行序各说各话）、诊断码 0x30xx 段独占（0x2C/2D/2E/2F 均已有主）） | VE 册 #VE-F2015 |
