//! | [`vea33_alias`] | F0033 别名与堆复用仲裁（显存别名安全域分析：活跃区间用**半开**区间 [begin,end)，端点相接不算重叠——闭区间会把逐帧连续绘制的相邻对全判重叠，别名功能整体失效；两资源同时活跃一律阻断且不降级（内容互相踩踏不是性能问题），不提供强制别名口子，阻断的对不进收益表不省显存；别名键必含对齐量——只看尺寸会漏对齐，把8字节对齐的资源别名到256字节对齐的块上逻辑跑得通但每次访问可能未对齐命中；安全先于收益判定，重叠对即便净收益很高也阻断；净收益=分开字节减共用块减别名开销，≤0即不别名（不为别名而别名）；共用块取两侧较大者；省下字节只累加正收益行，与净值合计口径分离；仲裁结论附两侧区间证据可复核（只给bool的结论无法复核，而仲裁失误即显存踩踏是最难查的一类）；候选对超预算登记非常规结论且不混入常规三类计数；读屏面板六行双语只报聚合计数不泄漏单对资源尺寸与内容哈希） | VE 册 #VE-F0033 |
//! | [`vea34_transient`] | F0034 瞬态资源分配器（帧内生命周期分析用**半开**区间 [first_touch,release)，端点相接不算冲突——闭区间会把首尾相接的流水绘制全判冲突，瞬态分配器整体失效；瞬态与持久**物理分池**，持久块绝不经瞬态空闲链表取用（否则帧末回收会释放持久资源在用的内存）；票据同时记「声明池 want」与「实际池 pool」两个字段，槽位归还看实际池、跨帧泄漏检测看声明池——降级票据声明瞬态而落持久堆，按实际池判泄漏会让它永远逃过检测、持久占用逐帧累积到耗尽而告警显示 0；池满**降级转持久堆并告知**（正确性优先于性能，不让渲染失败），降级既可观测（序号可查）又字节可查（供 A03 记账）；跨帧泄漏**检出与强制回收是两个独立计数**——只检不收则泄漏累积、只收不检则契约破坏静默；P95 取最近秩 ceil(0.95n) 而非均值（均值被大量便宜请求稀释、掩盖尾部劣化），耗时账为环形窗口只留最近 256 笔；耗时劣化可归因到具体请求序号（序号与样本同槽存储，环形淘汰后靠调用方回填映射必然对不上）；非法请求（零字节/超单块上限）**先拒不占槽位**，否则白占的槽会把后续合法请求全推去降级；块尺寸向上取整到256 字节粒度；读屏面板七行双语只报聚合计数、不泄漏单请求字节与槽位数） | VE 册 #VE-F0034 |
//! | [`vea35_readback`] | F0035 读回与映射策略（GPU→CPU 读回：**异步优先是默认而非兜底**——代价模型先算同步卡顿，只有「异步不可用」且「同步代价在预算内」才走同步，反过来写会让每次读回先付一次分支错误风险；卡顿代价模型**纯整数**（固定开销 + ceil(字节/带宽) 向上取整），因 no_std 无浮点保证且浮点会让同一输入在 Debug/Release 走向不同分支，向上取整刻意为之——低估卡顿会让本该切异步的请求留在同步路径上；预算比较用 `<=`（**恰好等于预算即达标**，等于即超出的写法会把达标读回平白推去异步多等一帧）；同步卡顿**自动切异步并告知**（静默切换会让「本帧就能拿到数据」的假设失效）；「异步不可用且同步超预算」的无路可走分支**按真实卡顿记账**而非按固定开销——否则恰好卡顿最严重的路径被排除在劣化统计之外，而那正是延迟归因要抓的对象；非法请求（零字节/超上限）**先拒不占延迟账样本位**，白占会把真实慢样本挤出环形窗口使 P95 好看；映射策略按**单帧写次数**阈值选持久/临时（阈值处持久总成本不高于临时，并留一档余量因持久映射占槽位且需显式解除、泄漏风险非零）；持久映射**必登记**，登记表满即拒且**不覆盖旧行**（覆盖会让先前映射失去登记⇒ 泄漏检不出）；映射泄漏**检出与强制解除是两个独立计数**，字节账同样归零（只检不收则泄漏累积，只收不检则契约破坏静默，且 A06 计量会持续虚高）；延迟账取最近秩 ceil(0.95n) 而非均值，环形窗口只留最近 64 笔，序号与样本**同槽存储**（靠调用方回填映射在环形淘汰后必然对不上）；读屏面板七行双语只报聚合计数、不泄漏单请求序号与字节数（资产布局信息）） | VE 册 #VE-F0035 |
//! | [`vea46_present`] | F0046 呈现器抽象与交换链管理（呈现子系统总纲**四件+两律**：交换链抽象/多缓冲/同步/热切换四件各有归属、呈现诚实与失败可见两律；**重建是三段原子事务**（校验→建链→换指针），任一段失败都不动现役链——「重建后随机黑屏」最常见的成因就是原地改写旧链让飞帧引用到已失效缓冲，故世代号单调且旧链保留到引用归零，仍被持有时销毁以CODE_STILL_REFERENCED 拒；**演练注入常态化**（重建失败是常态不是异常，驱动升级/热插拔/模式切换都会触发，故三段各有注入点，且注入失败**必须进账本**——判据 6 只钉「返回错误码+不换指针」时会漏掉「某段直接 return 不记账」，那样现场读账本的人看到零失败而链已停在旧世代，失败可见律分「必须发生」与「必须留痕」两半分别钉；**跨 API 统一按必选/可选两级**而非支持/不支持 bool：Vulkan 只有 fifo 是规范必选、mailbox/immediate 扩展可选，D3D12 的 immediate 走 independent flip 同样可选，Metal 只有 fifo——拍平成 bool 就丢掉了「这一档在**这台机器**上保证可用吗」这个唯一有用户意义的信息，判据穷举 3×3 全组合；**静态能力与查询能力分开**：Vulkan 的 maxBuffers 来自 surface 查询而非编译期常量，拿兜底常量当上限等于替 Vulkan 撒谎（真机只给 2 时 3 缓冲会被「通过」然后在驱动里失败），故查询源缺查询值即拒且查询值真参与上界裁决（夹逼对判据）；**必选 mailbox 需三缓冲是语义要求**（两缓冲下邮箱退化为保序，拿不到不撕裂且低延迟同时成立），与各家能力下界混同会放行「D3D12 必选 mailbox + 双缓冲」这条不成立的计划；**抽象违例一律拒绝不降级**（Metal×mailbox 降级会让调用方按 mailbox 延迟预算排帧却拿到 fifo 行为并收到「已用 mailbox」的确认）；**呈现诚实四值齐全**（已提交/已上屏/撕裂/未知，「未知」是不可省略的第四值——只有三值就不存在「我不知道」这一说），已上屏与撕裂必带帧号、已提交不得带帧号，帧号回退时诚实降级为「已提交未上屏」而非硬报成功；撕裂仅在链允许且显式请求时发生，链不允许时请求被忽略而非伪造撕裂；**归一层在出货路径上**（to_desc → rebuild 是两节唯一接缝，判据逐位比对现役链世代/缓冲/几何三要素，否则归一器可判据全绿而链由别处建出）；失败账本环形定容 32 但累计不减，越界取码返 None；读屏面板七行双语只报聚合计数与降级事实） | VE 册 #VE-F0046 |
//! | [`vea47_multibuf`] | F0047 多缓冲策略自适应（双/三缓冲自适应选择是**取舍表驱动**的——2×2 定容表（延迟紧/松 × GPU 忙/闲）是数据不是 if 链，四格各有结论与理由码，仅 Loose×Busy 默认三缓冲（忙且延迟预算宽松），Tight×Busy 保持双缓冲保延迟并计张力（吞吐压力交给丢帧升级信号，不预支延迟）；分桶边界不 off-by-one：P95 恰等于预算即 Tight（预算是上界）、占用恰 85 或帧耗时≥90% 周期即 Busy，u64 乘法防溢出；丢帧达阈值升一档且**只升不降**（丢帧是吞吐饥饿的直接证据，已三缓冲时丢帧信号无操作）；**同步地板联动 A48**：邮箱类同步抬三缓冲（两缓冲下邮箱退化为保序，与 F0046 mailbox=三缓冲语义对齐的约定常量，判据独立钉住），保序/立即类不设地板；**VRR 联动四值裁决**：窄窗（跨度<10Hz）视作定频不参与联动，生效 VRR×立即类冲突仲裁保 VRR（立即请求被挡且计数，不静默放行），生效 VRR×纯查表三缓冲降回双缓冲（VRR 已吸收波动，第三块缓冲只剩排队延迟），邮箱地板与丢帧场景对降档免疫（语义下界与饥饿证据优先）；**用户覆盖是覆盖不是重置**：手选双/三即生效于自动推荐之上，档外值拒绝计数且保留原覆盖（一次手误不把已手选的档静默重置成自动），手选与地板冲突不拦（用户主权）但冲突可见；**策略失配只建议不改档**：现役与推荐连续 4 次不符恰出一次建议并归零重计，现役追上即归零——建议是建议，命令是命令，现役档变更只有平滑过渡一条路；**过渡器只在静默点应用**：排空到无飞帧引用才切档（带飞帧硬换缓冲数等于让飞帧引用不存在的资源），排空超预算或应用注入失败即回退旧档且原因可查（切换失败→回退），同档切换是 no-op 不制造假排空，非静默点强应用被闸拒绝；出货接缝判据走完整链（评估→计划→排空→应用→回填现役档）；读屏面板七行双语只报聚合计数与策略事实，不泄漏单帧延迟） | VE 册 #VE-F0047 |
//! | [`vea48_vsync`] | F0048 垂直同步与邮箱模式（三档封闭全集 On/Off/Mailbox（wire 显式映射禁 as 直转）；**取舍是表数据不是注释**——MODE_TRADEOFF 定容三格，唯一零排队格与唯一撕裂预期格重合=Off 即「关同步省延迟但撕裂——用户自己选」的可对账形式；**用户选择是选择不是错误**：手选 Off 即生效不拦不降级，但撕裂告知义务同步建立（用户知情）；**模式切换原子事务**（校验→应用→确认，注入故障回退现役不变，同模式 no-op 不制造假事务，非帧边界强应用被静默点闸拒绝）；**独占×邮箱硬约束**（邮箱依赖合成器协调、独占绕过合成器，计划即拒专属码+显式退 On 计数留痕不静默）；撕裂账检测与告知 1:1、On 档撕裂异常单列专属码；延迟劣化按现役模式记账可查；V02 刷新率合法性前置裁决贴线不误拒；自持 MAILBOX_SEMANTIC_BUFFERS=3 与 F0046/F0047 语义对齐判据独立钉住；读屏面板七行双语只报模式事实与聚合计数） | VE 册 #VE-F0048 |
//! | [`vea49_framedisp`] | F0049 帧回调分发器（三段语义顺序表数据化（帧首=界面→脚本/帧中=渲染/帧尾=物理→脚本，PHASE_ORDER 表驱动不是 if 链，判据侧独立重算逐格对账）；**顺序契约双闸**——完整性闸（派到某格前之前每格「有在册即须全派」跳段即拒）+单调闸（游标不回跳），违例=断言拒绝+计数不纠错；**超时→告警+钳制**（超预算逐次告警，连续 2 次钳制：预算减半最低保底 500 钳不没，达标即解除可重复）；**回调泄漏→回收**（连续空闲 64 帧回收留痕，显式注销与回收分账）；统一分发全覆盖不重不漏、重复注册/段满/零预算/坏句柄全拒且拒绝计数；AC02 只产出执行序与超时事实不越权管线程池；读屏面板七行双语只报分发事实与聚合计数） | VE 册 #VE-F0049 |
//! | [`vea50_dropframe`] | F0050 丢弃帧检测与恢复（跳帧检测差步计数（checked 双保险零下溢面、帧号回退与同帧重present拒绝）、三类归因优先级仲裁（驱动节流>GPU忙>呈现阻塞，边界贴线即判、全不成立=Unknown 不硬猜）、原因不明入环形诊断包（满覆盖最旧如实计数、快照码稳定供 X04 剖析）、诊断模式状态机（连续 3 丢弃进入、连续 16 正常帧恢复退出、退出后<恢复窗复发=恢复失败升级逐次计数）、丢弃率环形窗口 O(1) 增量（ppm 整数口径判据侧独立重算对账）、输入响应影响量化（丢弃帧数×帧周期 u64 防溢出、档位表 0/1/2..=4/>4 逐档断言）、读屏面板七行双语只报丢弃事实与聚合计数） | VE 册 #VE-F0050 |
//! | [`vea51_fullscreen`] | F0051 全屏独占与无边框切换（三态封闭集（窗口/无边框/独占，wire 显式映射禁 as 直转）；**代价声明是公开数据表不是头注散文**（独占=绕过合成器+最低延迟+切出慢四格齐钉，无边框逐格相反，改表判据必红）；**用户确认是前置闸门**（代价声明→确认→切换顺序不可倒，未确认分码拒绝与系统拒绝分开——混码会把「用户不想切」读成「切不了」，拒绝计数留痕；同模式 no-op 免确认不开事务）；**三段原子事务**（校验→应用→确认，任一段注入失败回退：apply 前现役不动、confirm 段失败显式还原 apply 预登记——半切换态不落地；在途事务拒绝重入分码、跳段相位错拒绝不清账）；**抢占平滑回落写死无边框**（保住「占满屏」视觉语义只让出独占权，非语义随手默认；在途事务遇抢占一并回滚；非独占态不产生虚假回落）；V01 可用性事实本条只持有如实拒绝不裁决；读屏面板七行双语只报模式事实与聚合计数） | VE 册 #VE-F0051 |
//! | [`vef16_gridstat`] | F1613 网格统计与报告（单网格体检五项：顶点数/面数/LOD分布/压缩率/属性内存占用，五项皆已聚合故体检 O(1) 不遍历顶点；超标三态判定 Ok/Warn/Over 而非 bool——「恰好等于阈值」是合法值，只报 bool 会把它与「超出阈值」混为一谈，而阈值表正是为前者准备的；阈值表每项**必带依据**且空依据拒收（没有依据的数字是拍脑袋的，且没人知道该问谁），项目级覆盖非法值（warn>ceiling/floor>ceiling/无依据）**拒收并独立记账**而非静默夹取——静默夹取会让「我设了warn=100」看着生效实际存 90；面数上界取**三角网格拓扑上界 2V-4**（欧拉公式）而非 F<=V，后者会把立方体 8V/12F、二十面体 12V/20F 这类常规闭合网格全部误判自相矛盾；面数阈值上限刻意取 30 万而非顶点上限的 2 倍（40 万），因顶点数达 20 万时面数最多 399_996，取 40 万会让「面数超预算」这条判据**永不可达**（超它的网格必然先超顶点上限）⇒ 有标签 ≠ 可达；批体检复用 F1489 纪律：失败隔离（单条失败不炸批量）+ 断点续跑，且**零重复由「完成的定义」本身保证**（成功项进 done、失败项不进 done ⇒ 续跑自动跳过已完成、重试失败），而非额外判重逻辑；retry_count 口径为「同一 id **再次**失败」，首次失败不计——否则「重试 N 次」会把「N 个不同资产各失败一次」误读成「同一资产反复失败」，两者处置完全不同；报告开放导出**必带阈值口径与 ruleset 版本**，使报告离开模块后仍自解释、跨版本可比） | VE 册 #VE-F1613 |
//! | [`vef16_checks`] | F1613 域自检（34 项分 a/b/c 三族规避 MAX_CHECKS 截断：a=单网格14/b=批体检12/c=导出与判据集自身8） | VE 册 #VE-F1613 |
//! | [`vez01_vfxarch`] | F5201 Z 域开工与特效库总架构（Z 域定位：让画面会呼吸会说话——特效是内容的表情；域本色：特效即内容，为内容服务不为炫技服务，丰盛不以帧率为代价；四子系统粒子/后处理/环境/转场**责任互斥**，各产一类独占效果，跨类产出即越界——越界不靠自觉，靠归属判据逐类核对；两翼=参数系统（同一特效在不同场景取不同值）+组合系统（多特效按什么次序叠加），两翼是四子系统**唯一**的形参来源与编排入口，绕过两翼直接取常量则两翼形同虚设；特效即内容落在可测承诺上：无语义声明不入册、越权炫技被评审拦截且拦截有专属错误码不与参数越界合并、每个子系统受帧预算硬约束超预算登记降级不静默截断；层冻结=只能加不能改且加须升版本，改语义先走 unfreeze，直接改即越权；承接 Y 域 F5193 十件移交包（脚本绑定/渲染协议/预算口径三承接面），缺件回溯到源头件号；层间对拍必须能发现注入的失配而非恒真通过） | VE 册 #VE-F5201 |
