//! | [`vez13_testbench`] | F5213 特效测试（测试基准台不是用例堆——回归面齐备性是闸攻击全防是红线版本戳让结果不过期：**面齐备性先于用例执行**——五域闭集（四子系统+读屏环境格 a11y——无障碍不是附加题是必答题）每域至少 2 例，缺面 E_TB_CASE_MISS 拒跑（面不齐的套件跑出的绿是假绿）；**回归 fail-fast**——逐用例 sim_result 对拍 expect_pass 不符即停 E_TB_SUITE_FAIL；**钳制与消解用例直打真实现**——六例钳制（超上界/超下界/范围内/恰双端点/另参数恰端点）直灌 F5207 Validator、三态消解（加入/顶替/互斥）直打 F5208 StackResolver——测试台消费上游真实实现而非复刻影子逻辑（影子绿了真实现红了测试就成了装饰）；**攻击全防红线级**——光敏四攻击参数全拦（任一 passed=漏检 E_TB_FLASH_LEAK 漏检不是缺陷是事故）+注入九载荷全拒（八形注入+一形类型错，任一 Ok=穿透 E_TB_BREACH），检测 O(参数数)；**版本戳**——build 号+域清单指纹 FNV 双对拍，上游改域清单→指纹变→旧结果作废 E_TB_BAD_VER（过期的绿比没有绿更危险）；**失败阻断收口同纪律**——套件失败/漏检/穿透任一→发版闸 blocked 置位阻断 O(1) 修完才能收口；Z 域字符串码五码互异） | VE 册 #VE-F5213 |
