//! | [`vel08_pool`] | F2208 粒子池与内存（**双配额防单发射器吞池**：池总配额=容量×stride 且 CPU/GPU 双池**闸门独立**（共享即等于只有一个总闸，GPU 超额会连带拒掉 CPU 分配）；单发射器上限默认池容量 10% 且**独立于总水位**生效——不设它时一个发射器就能吃满整池、其余发射器饿死，而池水位看着「正常」，小池占比算出 0 时兜到 1 槽（兜 0 会让任何分配都被判超限，一个都发不出去）；**三阈值 70/85/95 用夹逼对钉死界位置**（界下不进/界点进/界上进，只断「≥某值成立」会漏掉差一档的错位）；**滞回升降阈值分离**（70/65、85/80、95/90）——同值则水位在阈值上抖动时档位每帧翻转、发射率因子阶跃，视觉上是频闪，判据在死区中点与两端取样并与「无滞回」变体对拍；降级因子取**反比线性**（85%→1.0、90%→0.5、95%→0.0）而非阶跃，阶跃会让水位在 85 附近抖动时发射率 1.0↔0.5 跳变、比不改更难看，且判据断相邻 1% 水位的因子变化 <0.2；**空闲链表侵入式**（next 存在槽位数组自身，零额外分配），批量回收**头插**故链表序 = 批次序 + 原 free 序（**非逆序**——逆序会让「回收顺序=死亡顺序」这条契约静默失效，表现是粒子复用时属性错乱而非崩溃），判据用**乱序死亡语料**把头插与尾插劈开（语料里死亡位置恰等于槽位号时两者给出同一序列，判据恒绿）；**拒绝显性带三要素**（当前水位/上限/建议），超 95 新分配拒绝不静默截断——静默截断的后果是发射器以为在正常发射、画面上粒子就是不出现且无线索可查；**单发射器超限只截自己不连坐**（别家 EmitterBudget 计数逐项不变）；**泄漏账本两恒等式**（① 分配−回收 == 池实测在用，必须传真值——账本自比会把「有在用粒子」判成泄漏；② 死亡标记−已回收 == 死亡未回收累计），只断①会漏「死亡了但没还回链表」；降级通知事件三字段齐备且因子与水位自洽；如实记录：`checked_mul` 的溢出分支在当前 u32×u32 类型下**不可达**（(2^32-1)^2 < 2^64），保留它是防御性冗余而非需要判据覆盖的活代码 | VE 册 #VE-F2208 |
//! | [`vel08_checks`] | F2208 域自检（判据逐条映射，**100 项**，基线全绿；变异双向验证 **37/37 全捕获、零漏网零未施加**：① 阈值判据用**夹逼对**钉死界位置而非只断「>某值」；② 期望档位由判据侧**独立重算**（先按升档点定ceiling 再按回落点下压）而不调用被测 observe——否则「阈值写错」会同时改掉实现与期望值造成假绿，且回落判定是**严格小于**，恰在回落点仍保持原档；③ 回收顺序判据用**乱序死亡**反退化语料；④ 账本恒等式**传真值**（传池侧 live，传账本自算值则恒为 0 变成自证式弱门禁）；⑤ 越界死亡标志判据钉**dead_marked 计数**而非最终回收数——`reclaim` 内层还有一层等价过滤，只断回收数会被内层兜住而全绿；⑥ 配额超硬顶判据**不用 || 合并两臂**（或逻辑让任一臂为真即过，是弱门禁），且单独钉「恰好等于硬顶须通过」（`>` 改 `>=` 的变异靠这条抓）；⑦ 因子边界点专项（85 返回 1.0 / 95 返回 0.0 / 相邻 1% 跳变 <0.2）；⑧ 负向断言配正向计数（造足事件断恰等于 N，防「永远返回 0」骗过负向）；如实记录：三项**真等价变异**已从变异表移除并写明理由（整数乘除结合律、`<=`/`<` 在因子边界的数值重合、u32×u32 溢出分支不可达），按纪律「MISSED 先怀疑变异选错」改产出侧而非加抓不到的假判据 | VE 册 #VE-F2208 |
//! | [`vel09_debug`] | F2209 粒子调试数据（**双层统计**：池级直读 F2208 计数器（live/水位/档位零额外计算，单一事实来源——调试面自己再算一遍迟早漂移且排查不知道信谁）+ 发射器级事件计数，每秒聚合进**定容环形缓冲**（只保最近 64 秒，调试流的价值在最近不在全量）；**统计洪水 TopN 降档**：千级发射器只交付按在用数排序的前 64（序稳定键 live 降序+id 升序，不依赖排序实现——否则换个 sort 榜单跳位），其余**聚合成 others 桶不丢弃**，TopN 和+others 恒等于全体和的**守恒式**让降档可对账——只发 TopN 丢其余会让统计面与池面对不上，降档本身在撒谎；**gizmo 五形状线框**：形状类型/参数校验/圆周逼近全部复用 F2203 单源（两份几何迟早漂移，漂移后 gizmo 画的形状与实际发射域不一致=调试数据本身在撒谎），点=三轴十字/线=两端点/球=三大圆/锥=底环+辐条/网格=包围盒 12 棱；**双级 LOD**：距离四档（1/1·1/2·1/4·1/8，下限 3 段防圆退化成点=gizmo 突然消失）+ 预算折半减密，抽稀前顶点数如实记账（不记账则绘制端把简化线框当真实形状）；**力场预留位 STUB 显性报错**指路 F2230（静默空数据会让消费端把没实现误读成没有力场）；**信封 L 段两类型注册**（粒子统计/gizmo，线上码显式映射不用 as u16），力场预留码 0x03 故意不注册（预留=位置留着实现未到，不是可以当已实现用），FNV 对账漂移即拦截（消费端一律取不到——只记不拦等于把红线降级成日志）；**发行版剔除零成本**：Release 档连强行尝试都不递增构建计数（不是构建完再抹掉而是根本不进入构建），Debug 是安全默认） | VE 册 #VE-F2209 |
//! | [`vel09_checks`] | F2209 域自检（判据逐条映射，十族；**双向验证**：剔除零成本 Debug 档计数器真的递增（对照组证明计数器不是死的）+ Release 档连强行尝试都不递增，只断后者会被「字段恒 0」的实现骗过；洪水守恒式配「others 非空」前置断言（others 为 0 时守恒恒真是弱门禁）且全体和由判据侧独立累加（不调被测 all_live_sum，否则累加写错同时改掉实现与基准）；LOD 期望顶点数按几何公式独立重算（球=6×segs/锥=4×segs/点=6/线=2/网格盒=24）；洪水语料 live=(i×7)%53 与下标异相（反退化：live 恰等于建档序时「按 live 排序」与「按序取前 N」同一榜单）；榜首 id=15 由 7⁻¹ mod 53 数论独立推算；判据区零 panic 面，取值一律 .get()/match 记红；容量纪律：十族原始 153 条超 MAX_CHECKS=112，按同域分族先例拆 a/b 两集 standalone 注册（78+75），合并路径在注册表上不可达） | VE 册 #VE-F2209 |
