//! | [`vee11_textdoc`] | F0811 文字渲染手册（**手册由词条表生成**而非手写文档：文字渲染域参数密度全域最高（F0807 合批2000 / F0808 查询 0.001ms / F0810·F0831 沙箱 64MB·500ms / F0816 单字形 2ms），手写必然漂移且**不自曝**——代码改了文档不改，读者照旧数字调参而文档看着还是对的；故正文每个数字从词条表渲染，词条表每条挂**代码常量引用**（`source` 形如 `F0817::ERR_CODE_SEGMENTS`），人只写句子的 connective tissue；漂移因此变成可机器检出的（`audit_text` 查缺行/值旧/裸数字/缺互链/缺版本）；**三读者六节均为封闭枚举**——`Section::ALL` 遍历生成六节，漏写一节只能显式删`ALL`，而那会同时删掉 `COUNT` 的自洽性，判据立刻红；读者覆盖另要求每位≥2 节（只被一节覆盖=手册结构无冗余兜底）；节掩码与词条实际归属须**不脱节**（声明「这节面向你」却无一条参数与你相关＝骗读者）；三症状树的每个排障动作**必须绑定真实词条键**（绑不上就是许愿不是排障）；无障碍三项**独立计数不做总分**（总分能让「对比度满分+十个图没替代文本」显示成合格）；WCAG 对比度走**整数路径**（`c^2.4 = c²·(c²)^(1/5)`，真no_std 无 `f32::powf`），**黑白恒 21.000×** 是归一化是否正确的唯一硬判据；审计实测判定 WCAG 经典链接蓝 `#0000EE` 仅 3.405:1 **不达正文级**故改深靛 `#1A3E6E`（10.284:1），被拒蓝保留为反向基准使「为何不用它」有数值依据；性能落成**确定性工作量预算**（无墙钟环境），另钉「同输入两次生成逐字节相同」——不可复现的手册没法抽查） | VE 册 #VE-F0811 |
