//! | [`vee12_textqa`] | F0812 文字渲染测试资产（金样集 **32 字体×8 字号×3 档 Hinting=768 组合**为唯一真源，「逐字体齐备」比逐条登记更强——少一组合即该字体不完整；**diff 阈值 0.5% 走整数交叉相乘**（`diff*1000 <= total*5`）而非除法，因为金样动辄百万像素，除法会因舍入把边界判反，且真 no_std 下没有 `f32::powf` 可依赖；`total==0` 必须判**非法样本**而非空图通过——空图参与判定等于没测；金样更新走**结构性拒绝**六闸：阈值不可现场放宽（0.5% 是常量不是参数）/ **GPU 路径不算合格参考**（GPU 差异即 flaky 源，于是 flaky 与真实回归不可分，只能固定软件路径做 diff）/ **双人复核判的是「互异」不是人数**——同一人点两下就冒充了双人，故须按身份去重后比数量；拒绝必须**真的不落地**，否则「先放行后补报告」行得通，「先入库再补复核」也行得通；四组测试是**三态**（Pass/Fail/**NotApplicable**）且 CI **只放行 Pass**——「没测」绝不能显示成「测过」，NotApplicable 在门禁里等于闭；预算区分**并行取关键路径（最慢组）、串行取总和**，混用二者会让并行省下的时间算进账上；6 分钟全量预算 360 秒逐组分账；冒烟把**编译 / 运行 / 退出码**分作三维——只看编译过会把「链接过了但运行即挂」放过去；度量对拍**缺失字段判 Missing 而不是 Agree**，「没跑」与「跑出一致」在语义上相反，混同则空对拍恒绿；基线差用**饱和减**，真值域 ±4294967295 超 i32，有符号溢出在 no_std 下是未定义行为；缓存水位是**可调字段**不是常量，判定读字段不读期望命中率（拿构造器常量当期望值即自证式）） | VE 册 #VE-F0812 |
