//! | [`veb233_dualscreen`] | F0233 Intel 双屏输出配置（**镜像共享 pipe 时序 = 只编程一次**——判据对拍 `timing_programs` 镜像恒 1、扩展恒等于活跃输出数；镜像多编程一次就多一次模式切换中间态窗口，正是花屏的来源；**扩展独立 pipe 按端口升序拿升序最低号**——`p0→pipe0/p1→pipe1` 是规范序而不是巧合，换个遍历顺序就换 pipe 号是最难查的显示 bug；**首个差异字段按规范字段序定位**（时钟→link rate→lanes→hdisplay→vdisplay→vrefresh）——用户看到「分辨率不同」而非六字段清单；**判定规则不重写真调 F0225**（`TimingSig::to_params` 装配后真调 `value_legal` + `bandwidth_ok`，复制规则会出现上游改表这里没改的静默分叉）；镜像下坐标归一并记账（改写不无声）；**拒绝 ≠ 半落地**（时序不一致/非法即拒绝：不动现状、不发下游请求、不占 pipe，屏幕保持上一份已生效布局）；**降级只针对扩展不是显示**（pipe 不足退单屏且副屏 placement 显式 `None`——不假装两屏都在；镜像只需一根 pipe 故同样资源下不降级）；**恢复走同一条 apply 管道不是后门**（记录可能记着三个月前两块 1080p 的镜像、今天副屏换 4K——走同管道则恢复与当场手选受同一套约束）；**头闸先于体解析**（魔数/版本/校验和三道独立拦下篡改，O(1) 反序列化才有可验证的形状）；校验和只覆盖除自身外的词位（把校验位也算进去会自指，封出来的记录自己校验不过——现场是"保存永远失败"）；模式时钟拆高低两词（u16 装不下 148500 kHz，`as u16` 截断即静默损坏）；降级也写回 applied（否则"当前布局"与"实际显示的东西"会说两套）；降级与拒绝两类可判定 `is_degraded`；三要素通知**键盘可达 + 可关闭是显式字段不是注释承诺**、七组三要素两两互异；上游 F0232 联动 `sync_with_hotplug` 真调 `LinkState::has_link()`，接入即发 F0226 MPO 重估（缓存必脏）；码独占 0x64 段七码、32 条判据全绿） | VE 册 #VE-F0233 |
